class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        count = Counter(nums)
        minHeap = []
        for num, freq in count.items():
            heappush(minHeap, (freq, num))

            if len(minHeap) > k:
                heappop(minHeap)

        return [num for _, num in minHeap]
